import { item } from "./items";
import type { PracticeBank } from "./items";

export const associateBank: PracticeBank = {
  practice: [
    item("bus-notice", "1.1", "prompt", "Maplewood School",
      "A road closure changes stops on two bus routes from Monday. The transport memo lists the new stop locations and times but gives no date for when normal service resumes. Families need a notice under 100 words by 3 p.m. The first draft, from the prompt 'Write a bus update for families,' guessed a two-week closure. Which instruction best fits the task?",
      "b", "A fit-for-purpose prompt names the audience, length, source and what to do when a fact is missing. Without a rule for gaps, Claude fills them with plausible specifics. Formats, summaries and outside timelines help only once the prompt says which source governs and how to mark unknowns.",
      ["Draft a short notice in last month's closure format, and use that notice's usual two-week period where the memo is incomplete.", "Reusing a format is fine, but the two-week period is exactly the unsupported guess that made the first draft unusable."],
      ["Write for families in under 100 words from the memo only, listing stops and times, and mark the resumption date unconfirmed.", "It names the reader, length and source, keeps the actionable stop details, and gives Claude an explicit rule for the missing date."],
      ["Summarize the memo for the transport director first, then ask Claude to rewrite that summary in a warmer, more conversational tone.", "A director's summary can drop the stop-level details families need, and a tone pass does not restore them or address the date."],
      ["List the affected routes, and fill the missing date from the road contractor's public timeline so families know what to plan for.", "Road works and bus service can resume on different dates, so the contractor's timeline does not support a service claim."]),
    item("two-policy-dates", "2.3", "grounding", "Maplewood School",
      "A draft reply tells a parent that applications close on 14 May and links to the approved admissions memo. Opening the memo shows two deadlines: 14 May for transfer students and 24 May for new enrollments. The parent's email says the child is starting school for the first time. The reply is due today. What should staff verify before sending?",
      "c", "A real citation can still support the wrong claim. Verify that the cited passage covers the same group, place and time as the statement in the draft, not just that the source exists and is current. Repeating the search or citing both dates leaves the reader exposed to the same error.",
      ["Confirm the memo is the latest version published on the school website, then keep the 14 May date the draft already cites.", "A current memo can still set different deadlines for different groups, and 14 May applies to transfers, not this family."],
      ["Ask Claude to search the memo again and accept the date if the second answer repeats 14 May with the same citation.", "A repeated answer can repeat the same scope error; agreement with itself is not independent verification."],
      ["Check which category the child falls under in the memo, then give the 24 May new-enrollment deadline with that same citation.", "This verifies both that the passage applies to this family and that the date matches, using the memo the draft already cites."],
      ["Keep the link to the full memo and include both dates in the reply, leaving the parent to work out which one applies.", "The parent may still pick the wrong date, and staff are better placed than the reader to apply the memo's categories."]),
    item("shared-faq", "3.1", "projects", "Lucas Branch Library",
      "Five librarians answer program questions in separate Claude chats. All five need the same approved 30-page FAQ and the same rule for referring exceptions to the branch manager, but they should not see each other's patron conversations. Last week two librarians quoted different FAQ versions that they had attached to their own chats. How should the team set this up?",
      "d", "Choose the capability that matches the sharing pattern. Project knowledge and instructions give every chat in a Project the same approved starting point, while separate chats keep each conversation's history apart. Attachments, examples and shared threads each fail either consistency or separation.",
      ["Attach the FAQ to the first chat, then ask each librarian to open a chat in the same Project, which inherits that attachment.", "Attachments belong to one chat; other chats in the Project do not inherit them, so versions would still diverge."],
      ["Publish an Artifact with one model answer and ask each librarian to copy its style and referral wording in their chats.", "A sample answer shows style but not the full FAQ or the referral rule, so librarians still supply their own versions."],
      ["Create one continuing chat holding each librarian's replies and a pinned copy of the FAQ, so the version stays consistent.", "A single thread exposes each librarian's patron conversations to the others, which the team must avoid."],
      ["Use a shared Project: the FAQ in project knowledge, the referral rule in Project instructions, and one chat per librarian.", "Every chat gets the same FAQ and rule from one maintained place, and separate chats keep patron conversations apart."]),
    item("review-window", "4.4", "eval", "Market Hall",
      "Stall operators send weekly updates that staff turn into a market bulletin. Drafting takes four hours and review takes 30 minutes, and policy says a staff member must approve any change to operating hours before publication. The director wants a four-week pilot with Claude that keeps the approval step intact. Which pilot design fits?",
      "a", "Integrate Claude where the work happens and keep the existing decision owner as a release gate. Measure the whole workflow against a baseline, including review effort and corrections, so the pilot shows real value rather than drafting speed on easy inputs.",
      ["Draft from stall forms in a Project, keep staff sign-off on hours changes, and compare total time and corrections to the baseline.", "The approval gate stays in place, and measuring total time and corrections captures both the saving and any new review burden."],
      ["Let Claude approve routine hours changes in the weekly bulletin, and have staff review a sample of those approvals each Friday.", "Policy requires approval before publication; a weekly sample reviews changes only after the public has already seen them."],
      ["Have staff draft as usual, and let Claude approve hours changes that move by less than one hour from the previous week.", "Policy covers every hours change regardless of size, and this places the approval with the model instead of staff."],
      ["Run a drafting trial on polished past bulletins and record how many minutes Claude takes to respond to each request.", "Polished inputs hide the difficulty of raw stall forms, and response time omits the review effort the pilot must measure."]),
    item("superseded-policy", "5.4", "projects", "Lucas Community Center",
      "A Project that drafts room-booking replies began citing last season's rules this month, including a cancellation fee that was removed. Project knowledge holds both rules-2025.pdf and rules-2026.pdf, and the Project instructions and reply Skill have not changed since spring. Only the 2026 rules apply to future bookings. What should the coordinator change first?",
      "b", "Trace a regression to the layer that changed or that the symptom points to. Two conflicting files in knowledge are a stale-knowledge signature, so remove the superseded file and test a case where the versions disagree. Changing unchanged layers or adding vague cues leaves the conflict active.",
      ["Keep both PDFs, and change the reply Skill's format so each answer shows a citation that staff can check by hand before sending a reply.", "Citations make the conflict visible but leave the 2025 rules eligible, so staff must keep catching the same error by hand."],
      ["Remove rules-2025.pdf from project knowledge, then test a booking question where the cancellation fee differs between the two seasons.", "This removes the superseded source and tests a case that passes only if the 2026 rules are the ones in use."],
      ["Start fresh chats with both documents still in knowledge, and add the word 'latest' to each request about booking rules.", "New chats read the same knowledge, and 'latest' gives Claude no reliable way to tell which file governs."],
      ["Rewrite the Project instructions to say current rules apply, and leave both PDFs in knowledge for historical reference.", "The instructions have not changed and were not the cause; the 2025 file left in knowledge can still be cited."]),
    item("field-minimum", "6.2", "privacy", "Maplewood School",
      "The school permits an approved Team workspace to classify 900 enrollment messages by topic for a staffing report to the board. Policy excludes student IDs and medical details from any AI tool. Staff need only topic counts, and many messages mention allergies or conditions in passing. Which TWO steps support this pilot?",
      "ad", "Minimize data before it reaches Claude and confirm that the exact fields and purpose fall within policy. Output instructions, partial pseudonymization and moving data into project knowledge all leave excluded content disclosed at the point of upload.",
      ["Keep only the topic-bearing excerpts, removing student IDs and medical details locally before anything is uploaded to the workspace.", "Minimizing before upload means the excluded fields never reach Claude, and topic counts still work from the excerpts."],
      ["Upload the original messages and instruct Claude to produce topic counts with no identifiers or medical terms in the output.", "Output rules act after the excluded data has already been sent as input, so the policy is breached at upload."],
      ["Replace student names with initials but keep IDs, so duplicate messages can be matched and removed during the analysis.", "Student IDs are explicitly excluded, and deduplication can be done locally before anything is uploaded."],
      ["Confirm the proposed fields, workspace and purpose in writing with the school's designated data owner before the pilot begins.", "Workspace approval does not by itself approve every input or use; the owner confirms this specific workflow."],
      ["Put the raw messages in project knowledge instead of attaching them to chats, so they stay inside the approved workspace.", "Changing where content is added does not change what is disclosed; IDs and medical details would still be uploaded."]),
    item("before-after", "7.1", "eval", "Juniper Kitchen",
      "A weekly refunds summary started omitting refunds on Monday. The prompt, Project instructions and model are unchanged. Monday's export switched refunds from negative amounts to positive amounts with a new 'type' column set to REFUND. Last week's export is still available. A colleague suggests switching to Opus. Which next step best isolates the problem?",
      "c", "Diagnose by changing one condition while holding the rest fixed. When the only known change is the input format, replay matched records in both formats through the same setup. Model swaps, vague instructions and file splitting add variables without testing the suspected cause.",
      ["Switch the chat to Opus, rerun Monday's export, and keep the model that identifies more refunds in the weekly summary.", "A model swap does not test the input change, and a lucky result would hide the unhandled type column."],
      ["Add an instruction to look harder for missing rows, then compare the word count of this week's summary with last week's.", "A vague instruction does not explain the new column, and word count does not measure whether refunds were caught."],
      ["Run matched rows from last week's and Monday's exports through the same prompt and see how the new type column is treated.", "Only the export format differs, so a difference in output isolates the changed representation as the cause."],
      ["Split Monday's file into four smaller files and compare the four summaries with each other to find where the missing refunds went.", "Splitting the file changes size, not meaning, and comparing summaries of the same format never tests the change."]),
    item("interview-plan", "1.2", "prompt", "Neighborhood Council",
      "Council members have 18 interview notes and must recommend two service changes by Friday. Three notes disagree about the library's Saturday opening hour. A staffer lists the steps: 1) Extract observations with note IDs. 2) Recommend two changes, flagging any unresolved conflict. 3) Ask the library manager to confirm the Saturday hour. 4) Compare the three conflicting reports side by side. 5) Send the recommendation to the council chair. Which order best preserves the evidence?",
      "c", "Decompose work so that evidence is extracted and conflicts are resolved by their owner before conclusions are drawn. Recommending first invites selective evidence, and comparing before extraction has nothing structured to compare. Put the validation checkpoint where an error would otherwise flow into the recommendation.",
      ["1, 2, 4, 3, 5", "Recommending before the conflicting reports are compared and confirmed builds the advice on an unsettled fact."],
      ["4, 1, 3, 2, 5", "The conflicting reports cannot be compared reliably before observations are extracted with their note IDs."],
      ["1, 4, 3, 2, 5", "Observations are extracted, the conflict is compared and confirmed by its owner, and only then is the recommendation drafted."],
      ["1, 4, 2, 3, 5", "The recommendation is drafted before the library manager confirms the hour, so it may rest on the wrong report."]),
    item("missing-shifts", "2.2", "eval", "City Dispatch",
      "A summary for the dispatch supervisor says 'most staff favor the new rotating schedule' and cites 32 survey responses. The survey link went only to weekday shifts; none of the 14 weekend dispatchers, who work 12-hour shifts under different constraints, received it. The supervisor wants to announce support at Thursday's briefing. What can the supervisor accurately say now?",
      "b", "A finding is limited to the population that was sampled. When a group was never asked, restrict the claim and say how the gap will be closed. Footnotes, reweighting and model estimates cannot create evidence about people who gave none.",
      ["Most staff favor the new schedule, with the response count of 32 shown in a footnote for colleagues who want more detail.", "The count does not reveal that weekend dispatchers were never asked, so the claim still covers people with no say."],
      ["Weekday respondents favor the new schedule; weekend dispatchers were not surveyed, so their view will be collected first.", "The claim now matches the sample, and the supervisor commits to closing the gap before speaking for everyone."],
      ["Most staff favor the schedule once the 32 responses are reweighted by the share of weekend staff on the roster.", "Reweighting adjusts groups that responded; it cannot supply views for a group that gave no responses at all."],
      ["Most staff favor the schedule, with Claude's estimate of weekend preferences from general research on shift work added.", "A general estimate is not evidence about these dispatchers, whose 12-hour shifts may lead to a different view."]),
    item("rota-model", "3.3", "models", "Market Hall",
      "A helper sorts vendor emails into 12 fixed categories. A 500-email trial found Haiku, Sonnet and Opus all met the 95% target on routine mail; on the 6% of emails that are ambiguous, accuracy ranged from 70% to 88%. Staff have a hard monthly budget and can review flagged items within a day. Which rollout is most appropriate?",
      "a", "Use the lowest-cost option that meets the measured target, and route the hard slice to people when no model is reliable enough there. Then monitor the routing itself for misses. Paying for capability that brings no measured gain, or trusting labels without a check, both misread the trial.",
      ["Use Haiku for routine mail, flag ambiguous emails to staff, and audit a monthly sample of the routing itself for misses.", "It meets the routine target at the lowest cost, sends hard cases to people, and checks whether ambiguous mail slips through."],
      ["Use Opus for each email to get the best ambiguous-case accuracy, and cut staff review of flagged items to offset the cost.", "Opus brings no routine gain, 88% is still short on ambiguous mail, and cutting review removes the safety net."],
      ["Use Haiku for routine and ambiguous mail and treat each assigned category as final, since the trial showed it meets the target.", "The trial showed the target met on routine mail only; ambiguous emails would be misfiled with no check."],
      ["Alternate between the three models by day and keep the one that clears the most emails per hour during the first month.", "Day-to-day differences in email mix confound the comparison, and throughput says nothing about whether categories are correct."]),
    item("pilot-brief", "4.5", "eval", "Maplewood School",
      "A two-week trial on 30 parent replies cut drafting from 12 to 5 minutes per reply. Review time rose from 2 to 6 minutes because staff checked each policy reference, and reviewers corrected 2 of 30 drafts for policy errors before sending. The principal asks the project lead for a one-line summary to share with the board. Which summary should the lead give?",
      "d", "Communicate value and limits together. Report the net change across the whole workflow, the observed error rate and the oversight that remains necessary. Single-stage savings overstate the result, a review-only view understates it, and claims about catching every error go beyond the evidence.",
      ["The pilot saved seven minutes per reply, and reviewers caught the policy errors before replies were sent to parents.", "Seven minutes counts drafting only, and a 30-reply trial cannot establish that every possible error was caught."],
      ["The pilot saved 58% of staff time on replies, so review can become optional once staff are comfortable with Claude.", "58% describes drafting time, not total time, and review is where the two policy errors were found."],
      ["Review time tripled during the pilot, so Claude reduced overall productivity and should not be extended to other teams.", "This ignores the larger drop in drafting time; total effort fell from 14 to 11 minutes per reply."],
      ["Total time fell from 14 to 11 minutes per reply; staff corrected 2 of 30 drafts, so the checking step stays.", "It reports the net effect across both stages, the observed error rate, and why oversight stays in place."]),
    item("persistent-rules", "5.3", "projects", "Lucas Branch Library",
      "In a shared Project, every program reply must list the accessibility contact and use plain language. The program calendar the replies draw on changes monthly. Right now staff paste both rules and the calendar into each chat, and an audit found 6 of 50 replies missing the accessibility contact. Where should staff maintain the rules and the calendar?",
      "a", "Split persistent design by how often things change: stable behavior goes in Project instructions, changing reference material goes in project knowledge and is replaced when it changes. Per-chat pasting, titles and saved chats depend on someone remembering, which is what the audit caught failing.",
      ["Put the two rules in Project instructions and the current calendar in project knowledge, replacing the file each month.", "Every chat receives the rules automatically, and the calendar is maintained once in the place Claude consults for facts."],
      ["Put the two rules in the calendar file's title and refresh that file monthly, so the rules travel with the calendar file to each chat.", "A file title is incidental metadata, not an instruction, so Claude may not treat it as a required behavior."],
      ["Record the rules and calendar in one well-reviewed chat, and link that chat from a new Project created each month.", "A previous chat does not supply instructions or knowledge to new chats, so staff would still paste by hand."],
      ["Keep the rules and calendar in a reusable reply template that staff paste in and edit after Claude responds.", "This keeps the manual pasting that caused the six omissions and leaves the rules outside Claude's standing instructions."]),
    item("volunteer-ranking", "6.1", "safety", "Lucas Community Center",
      "The center runs a paid apprenticeship and wants Claude to rank 60 applicants for 12 places. Center policy requires staff to apply published criteria and record reasons, and Anthropic's Usage Policy treats employment decisions about people as high-risk, requiring meaningful human review and disclosure that AI was involved. Where can Claude contribute under these rules?",
      "b", "In high-risk uses, Claude can organize evidence for the people who decide, but a qualified human must make and be able to change each decision, and affected people should know AI was involved. Cutoff bands, tie-breaking and agreement rules all let the model decide some outcomes.",
      ["Rank applicants against the criteria and send staff the applicants within one point of the cutoff, disclosing AI use in letters.", "Disclosure is required but not enough; most outcomes would be decided by the model with no staff review."],
      ["Extract cited evidence into the criteria worksheet; staff score and record each decision, and applicants learn that AI assisted.", "Staff remain the accountable decision makers with evidence they can check, and disclosure meets the policy requirement."],
      ["Rank anonymized applications and use Claude's ranking to settle cases when two staff reviewers disagree about an applicant.", "Anonymizing inputs does not transfer decision authority; in contested cases the model would make the call."],
      ["Produce a separate ranking and adopt it wherever it agrees with one staff reviewer, recording that agreement as the documented reason.", "Agreement with one reviewer is not the documented staff decision, and it overrides the other reviewer's judgment."]),
    item("stable-brief", "7.3", "claudeSkills", "Washington Printworks",
      "Proof reviewers retype the same six requirements, such as bleed, color profile and font embedding, into every review chat. The requirements are stable, but the artwork and order number change each time. Of 80 recent reviews, 11 missed a requirement, each traced to an omitted line. Skills are enabled for the team. What change should be tested first?",
      "c", "When a stable procedure is retyped for every run and omissions trace to the retyping, package it once as a Skill and pass only the run-specific inputs. Then measure misses on matched cases. Longer threads, output length and restating notes keep the manual copying that causes the errors.",
      ["Combine the last ten proof review chats into one continuing conversation so the requirements stay in context for each new order.", "Past orders' details crowd the context, and nothing guarantees each requirement is applied to the new artwork."],
      ["Raise the output length limit in the prompt so Claude has room to mention the six requirements in each proof review.", "Output length cannot restore a requirement that was left out of the input; the omission is upstream."],
      ["Package the six requirements as a shared Skill, pass only the artwork and order number, and compare misses on matched proofs.", "The procedure is maintained once and applied the same way each time, and matched proofs show whether misses fall."],
      ["Ask staff to put the requirements in free-form notes and have Claude restate them at the start of each review.", "Staff still copy the requirements by hand, so the omission that caused 11 misses can recur in the notes."]),
    item("paired-tones", "1.3", "prompt", "Maplewood School",
      "When an application is incomplete, the first draft sounds accusatory: 'You failed to submit required documents.' A follow-up prompt, 'Make it friendlier,' produced a warm reply that dropped the list of three missing documents parents need to send. The list comes from the verified checklist in the chat. Which iteration should staff test?",
      "c", "Iterate by stating both what should change and what must stay invariant. An example can steer tone, while an explicit constraint protects required content. Effort changes and unrelated sources do not say which facts must survive, so the same trade-off reappears.",
      ["Ask again for a friendlier reply in the same chat, and review only the opening line to confirm the tone has improved.", "The document list can disappear again, and checking only the opening line would never notice that it did."],
      ["Repeat the original prompt at a higher effort setting so Claude balances the tone and the required content on its own.", "Effort does not describe the tone wanted or say the list is mandatory, so the original problem remains."],
      ["Give one neutral example reply, and state that the three-document list from the checklist must appear unchanged in the reply.", "The example shows the tone change, and the constraint states exactly which content must survive the rewrite."],
      ["Paste a friendly email from another school as the only reference, and ask Claude to match its tone for this reply.", "Its tone may transfer, but it carries none of the required facts and invites copying details that do not apply."]),
    item("different-deliverables", "1.4", "prompt", "Neighborhood Council",
      "The council needs ideas for a spring neighborhood event and, separately, a summary of what the budget committee approved on 3 March. The minutes are in project knowledge. An earlier single prompt mixed the two tasks, and the summary described a 'proposed food festival' as approved spending. Which pair of instructions matches the two tasks?",
      "a", "Different task types need different prompting strategies. Ideation benefits from freedom within constraints; a factual summary must be bound to its source. Letting the two share a prompt or a source lets proposals leak into the record as if they were decisions.",
      ["Brainstorm within the budget and venue limits; summarize approvals from the 3 March minutes alone, quoting each item.", "Each instruction fits its task: open ideation with limits, and a summary bound to the record with quotes to check."],
      ["Require minute citations for each event idea, and work out which items were approved from patterns in earlier years' events.", "This constrains ideas where freedom helps and lets the factual summary rest on inference instead of the minutes."],
      ["Ask for one clear recommendation that covers both the event ideas and the committee's approvals in a single page.", "Merging the tasks is what blurred proposals with approvals in the first place, and confidence adds no accuracy."],
      ["Draft the event ideas first, then use that draft as the main source for the summary of what the committee approved.", "Event ideas are not records of approval, so this would present the council's proposals as committee decisions."]),
    item("fee-and-hours", "2.1", "grounding", "Community Center",
      "A caller asked about both the room deposit and the deadline for a refundable cancellation. Claude's reply states the correct $150 deposit but omits the 14-day cutoff. Last month 9 of 60 replies missed at least one of the two facts. The coordinator wants a check that catches this across future replies. Which check should the coordinator use?",
      "d", "Evaluate outputs for completeness as well as accuracy, against the request and the governing source. A check that covers one field, uses length as a proxy, or confirms a link works will pass replies that are correct about what they say but silent on what the caller needed.",
      ["Verify the deposit amount in each reply against the fee schedule, since money is the highest-risk field for complaints.", "This checks accuracy of one field and would pass the reply that omitted the cancellation cutoff entirely."],
      ["Flag replies under 80 words for a second look, since short replies are the ones most likely to leave a fact out.", "A long reply can still omit the cutoff, and length says nothing about whether the stated facts are right."],
      ["Confirm that the policy link in each reply opens the current fee page, then approve the reply for sending.", "A working link shows where the facts live, not that the reply includes both facts the caller asked about."],
      ["Check each reply for both the deposit and the cancellation cutoff, comparing each one against the approved booking policy.", "It tests completeness and correctness for the two facts callers ask about, against the source that governs them."]),
    item("outdated-route", "2.4", "grounding", "Transit service desk",
      "Claude's reroute directions match the current published map. A same-day dispatch note says the Oak Street stop has moved 'to the other side of the bridge' but gives no confirmed location, and the map has not been updated. Riders will use the directions this evening. The dispatch supervisor is on shift. What is the next step before publishing?",
      "b", "When a live operational source contradicts the standard reference and the fact affects people's actions, confirm with the owner of that fact before publishing it, and hold only the affected part. Choosing by recency, defaulting to the map or inferring a location all publish an unverified direction.",
      ["Publish the map's stop location, since the map is the standard reference and the dispatch note gives no exact replacement.", "The same-day note calls the map's accuracy into question, so riders could be sent to a stop that has moved."],
      ["Hold the Oak Street direction, ask the dispatch supervisor to confirm the new stop, and publish the other directions now as planned.", "The disputed fact goes to its owner while unaffected directions still reach riders on time."],
      ["Publish the dispatch note's description as the new direction, since it is the more recent of the two sources.", "The note gives no confirmed location, so riders would get a vague direction that may not match the real stop."],
      ["Ask Claude to infer the most likely replacement stop from nearby routes, and publish that location with a caution note.", "An inferred stop is not an operational decision, and a caution note does not make a guessed location safe."]),
    item("one-decision-two-audiences", "2.5", "prompt", "Market Hall",
      "The market's closing time moves from 6 p.m. to 5 p.m., with load-out ending at 5:45. Staff need the full closing checklist with these times; vendors need a 60-word announcement. A first attempt asked Claude for 'two creative rewrites,' and the vendor version said load-out ends 'around 6.' How should the drafts be revised?",
      "c", "Adapt vocabulary and detail to each audience while holding the operative facts constant. Draft every version from one verified fact list and check those facts across versions before release. Creative rewrites, identical documents or a single short notice either change facts or fail one audience.",
      ["Publish the full staff closing checklist to vendors as well, so both audiences receive exactly the same instructions and times.", "Vendors would get operational detail they cannot use, and the 60-word announcement they need would not exist."],
      ["Ask for two fresh creative rewrites and let each version simplify the times in whatever way reads best for its audience.", "Letting each version simplify times is what produced 'around 6'; the operative facts must not vary."],
      ["Draft the staff checklist and vendor notice from one agreed list of the two times, then check both show 5:00 and 5:45.", "Each audience gets the right level of detail, and the cross-check confirms the facts are identical in both."],
      ["Use the 60-word vendor notice as the staff procedure too, adding a line telling staff to ask a supervisor for the details.", "Staff need the full checklist to apply the change; the short notice omits the steps they are responsible for."]),
    item("reusable-checklist", "2.6", "artifacts", "Washington Printworks",
      "Two colleagues want to revise a 40-item preflight checklist beside their Claude conversation over the next week. A downstream importer separately needs a machine-readable array of item IDs, and last time IDs copied from prose included two duplicates. Artifacts and code execution are enabled on the team's plan. Which output pairing fits?",
      "a", "Choose a format per consumer. People revising a standalone document need an editable Artifact; a machine import needs structured data generated from the source and checked. Prose, screenshots and instructions are not deliverables either consumer can use directly.",
      ["An Artifact for the editable checklist, and a JSON array of IDs generated with code execution and checked for duplicates.", "Colleagues revise the checklist beside the chat, and the importer gets computed IDs with the duplicate problem tested."],
      ["One long inline reply holding the checklist, and an instruction for the importer team to pick the item IDs out of the prose.", "Picking IDs from prose is the step that produced duplicates, and a long reply is awkward to revise in place."],
      ["A screenshot of the checklist for the colleagues, and a second screenshot of the ID list for the importer to retype.", "Screenshots cannot be edited or parsed, so both consumers would retype content and reintroduce errors."],
      ["The checklist and IDs stored in Project instructions, so each chat in the Project can reproduce both on request.", "Instructions shape behavior; they are not the editable document or the validated array either consumer needs."]),
    item("model-families-trial", "3.2", "models", "Lucas Branch Library",
      "A librarian can trial two Claude models this week. One job tags 3,000 catalog records a day with 20 simple subject labels; the other is about ten demanding comparisons a week of conflicting grant guidelines across five documents. Results must be defensible to the branch manager, who watches usage closely. Which first comparison makes sense?",
      "d", "Match model family to task profile: a fast, low-cost tier for high-volume, well-defined work, and a more capable tier for rare, complex reasoning. Then test each against real labelled examples and usage so the choice can be defended. Recency and throughput alone are not evidence of fit.",
      ["Trial Opus on the tagging and Haiku on the grant comparisons, judging each model on its throughput per hour alone.", "This reverses the sensible starting candidates and ignores the quality of the demanding comparisons entirely."],
      ["Use a single model for both jobs and estimate its cost from the number of chats the librarian opened during the trial week.", "It leaves the difference between the two jobs untested, and chat counts do not reflect actual usage."],
      ["Select the newest model available for both jobs, since the latest release is likely to be the best fit for each.", "Release date does not establish fit for either job, and the manager needs evidence rather than an assumption."],
      ["Trial Haiku on routine tagging and Opus on the grant comparisons, scoring each against labelled examples and usage.", "Each job starts on the tier suited to it, and labelled examples plus usage make the choice defensible."]),
    item("handoff-context", "3.4", "claudeMemory", "Market Hall planning",
      "A 90-message chat mixes planning for two events: a spring fair whose dates are verified and an autumn concert still in brainstorming. The next team owns only the spring fair. Their workspace lets members turn memory off for a chat from the '+' menu, and the old chat's author has memory on. What should the coordinator do?",
      "b", "Carry forward decisions, not the whole thread. A short, approved handoff in a fresh chat gives the next team what it needs, and turning memory off before the first message keeps earlier, unrelated context from resurfacing. Forgetting requests and broad copies leave the noise in reach.",
      ["Continue the old thread and ask Claude to forget the autumn concert, so the spring fair dates stay available in context.", "The concert brainstorming remains in the conversation's context regardless of the request to forget it."],
      ["Open a new chat with memory off before the first message, and paste a short approved handoff of the spring fair dates.", "The new team gets only verified spring fair facts, and memory cannot reintroduce the unrelated concert planning."],
      ["Start a clean chat with no handoff, since memory will carry the verified spring fair dates into the new conversation.", "Memory is not a reliable carrier of specific verified dates, and it may bring concert ideas along with them."],
      ["Copy the full 90-message conversation into project knowledge so that future chats in the Project can see both events' planning.", "This spreads unverified concert brainstorming into every future chat instead of isolating the spring fair."]),
    item("where-to-pilot", "4.1", "eval", "Washington Printworks",
      "A manager wants Claude to improve proof handling. Staff report that color checks take two minutes, approvals wait a day, and most rework comes from mismatched job numbers. The manager lists steps: 1) Map the proof workflow and time each stage. 2) Choose the pilot target. 3) Confirm which steps the approval policy allows Claude to touch. 4) Count rework causes over the last 50 jobs. 5) Run a two-week pilot. Which order identifies the right use case?",
      "c", "Identify requirements before choosing a use case: map the work, gather evidence on where problems arise, confirm the constraints that limit what may change, and only then pick a target. Choosing first tends to optimize the most visible stage rather than the costly one.",
      ["2, 1, 4, 3, 5", "Choosing the target before mapping the workflow means the pilot is picked before anyone knows where time or rework arises."],
      ["1, 2, 4, 3, 5", "The target is chosen before rework causes are counted and before the policy constraint is checked."],
      ["1, 4, 3, 2, 5", "The workflow is mapped, rework evidence gathered and the policy constraint confirmed before the target is chosen."],
      ["1, 4, 2, 3, 5", "The target is chosen before confirming the approval policy, so the pilot may target a step Claude cannot touch."]),
    item("wait-time-breakdown", "4.2", "eval", "Community Center",
      "Room bookings take a median of two days. Logs show Claude drafts each confirmation in about ten minutes; requests then wait in a one-day staff queue, and 30% of forms omit the event date and need a follow-up email. The manager wants to know where to focus improvement effort. What is the most informative next analysis?",
      "b", "Research a process by separating waiting time from processing time and comparing slices that differ in a known cause. That shows which change could move the outcome. Measuring only the AI step, excluding inconvenient stages or replacing the process wholesale hides the real constraint.",
      ["Measure Claude's drafting time per confirmation across a month and use it to forecast the full turnaround for bookings.", "Drafting is ten minutes of a two-day wait, so it cannot forecast or explain the turnaround customers experience."],
      ["Compare processing and waiting time for complete and incomplete forms, stage by stage, in last quarter's booking logs.", "This separates queue time from the follow-up loop and shows how much the missing-date problem adds."],
      ["Exclude the approval queue from measurement, since Claude cannot change it, and focus the analysis on drafting quality.", "The queue still drives the delay customers feel, and drafting quality is not the problem the logs point to."],
      ["Replace the process with automatic booking for one month and compare the number of bookings handled per week.", "This changes several things at once, removes existing review, and measures volume instead of delay."]),
    item("prototype-order", "4.3", "eval", "Neighborhood Council",
      "Residents often leave the date out of service requests. The council can change its web form and add a Claude drafting step, but cannot change referral rules this month. Steps: 1) Make the date field required on the form. 2) Record the current omission rate and staff time. 3) Measure omissions with the form change alone. 4) Add the Claude drafting step and measure again. 5) Report results with referral rules unchanged. Which order makes the result attributable?",
      "a", "Design and revise a solution so each change can be credited: record a baseline, introduce one change at a time, and measure after each. Changing things before the baseline, or adding two changes before measuring, leaves any improvement impossible to attribute.",
      ["2, 1, 3, 4, 5", "The baseline is recorded first, then each change is measured on its own, so each improvement can be credited."],
      ["1, 2, 3, 4, 5", "The form changes before the baseline is recorded, so the 'current' omission rate already includes the change."],
      ["2, 1, 4, 3, 5", "The drafting step is added before the form change is measured alone, so the two effects become mixed."],
      ["2, 4, 1, 3, 5", "Adding Claude before the form change means the 'form alone' measurement is never actually taken."]),
    item("project-setup", "5.1", "projects", "Lucas Branch Library",
      "A new library Project needs three things: the catalog subject terms staff must use, a consistent reply template with fixed sections, and a five-step procedure for building the monthly new-acquisitions list as a spreadsheet. New staff should get all three as soon as they open a chat in the Project. Which setup supplies them?",
      "d", "Place each requirement in the layer built for it: facts and reference lists in project knowledge, standing response behavior in Project instructions, and a reusable multi-step procedure in a Skill. Cramming everything into one layer or one message makes it harder to maintain and apply.",
      ["Name the Project after the template, and paste the subject terms and monthly procedure into the first message of each new chat.", "A Project name supplies nothing to Claude, and pasting into each chat duplicates maintenance and varies by person."],
      ["Upload the terms, template and procedure to a personal chat and share its link with new staff as the starting point.", "A shared chat link is a separate conversation, not Project context, so new chats in the Project receive none of it."],
      ["Put the subject terms, template and five-step procedure together in the Project instructions as one long standing rule.", "Reference terms and a multi-step procedure bury the reply rules and are harder to update in a single instruction block."],
      ["Put the subject terms in project knowledge, the template in Project instructions, and the monthly procedure in a shared team Skill.", "Each element sits where it is maintained and applied best, and every new Project chat receives all three."]),
    item("connector-access", "5.2", "projects", "Regional arts office",
      "A program team wants Claude to reference the 'Grants-Public' folder through a Google Drive connector. A sibling folder, 'Grants-Restricted,' holds reviewer scores, and both contain handbooks with similar names. The connector acts with each user's own Drive permissions. Before adding it to the team's Project, what should the team verify?",
      "c", "A connector reaches what the authenticated user can reach, so verify access at the permission level and test that retrieval returns the intended current source. Prompts, naming conventions and after-the-fact citation review do not prevent restricted content from entering a conversation.",
      ["That a Project instruction lists Grants-Restricted as off-limits, so Claude declines to quote from it during the team's work.", "An instruction is not an access control; anyone whose account reaches the folder could still pull reviewer scores in."],
      ["That both folders share the same handbook naming scheme, so Claude can tell from the file date which handbook is current.", "Naming and dates do not restrict which files can be retrieved, and similar names are part of the risk."],
      ["That team members' Drive access excludes Grants-Restricted, and that a test query returns only the current public handbook.", "Access is limited where the connector enforces it, and the test confirms Claude retrieves the right handbook."],
      ["That a teammate whose account already sees both folders can connect it, with staff reviewing citations in each draft.", "That account exposes reviewer scores, and reviewing citations happens only after restricted content was retrieved."]),
    item("exception-owner", "6.3", "plugins", "Juniper Kitchen",
      "Company policy allows anonymized supplier notes in Claude but requires written approval before any connector reaches a shared mailbox. The purchasing team uses an approved plugin whose bundled Gmail connector reads their mailbox. The kitchen team wants to install the same plugin against its own shared mailbox today, arguing it is 'already approved.' What should happen first?",
      "b", "Approval attaches to a specific access and purpose, not to a tool in general. A plugin approved for one mailbox does not authorize its connector to reach another. Follow the policy's order: approval first, then access, rather than relying on later anonymization or a pilot.",
      ["Install the plugin against the kitchen mailbox today, since the company has already approved the same plugin for the purchasing team.", "The approval covered purchasing's mailbox; policy requires written approval for each shared mailbox the connector reaches."],
      ["Request written approval for the kitchen mailbox, its purpose and the fields needed, then install the plugin's connector against that mailbox.", "This follows the policy for the actual access requested, and the plugin is connected only once approval exists."],
      ["Connect the kitchen mailbox and ask Claude to anonymize each supplier note as it is retrieved, as policy allows anonymized notes.", "The mailbox would be accessed before approval, and anonymizing after retrieval does not satisfy the approval rule."],
      ["Connect the kitchen mailbox during a one-week pilot, then request approval if the results justify keeping it connected afterward.", "Policy requires approval before access; a pilot is still unapproved access to the shared mailbox."]),
    item("language-effects", "6.4", "eval", "Lucas Community Center",
      "Claude's first triage pass labels six residents 'uncooperative.' All six wrote requests of one or two short sentences; residents with the same needs who wrote longer messages received no label. Staff must route requests by the service needed, and routing determines how quickly residents are contacted. What should the coordinator do?",
      "d", "When a judgment tracks writing style rather than relevant facts, remove it from the decision path, route on what the task requires, test for uneven errors across styles, and keep people able to correct consequential outcomes. Hiding or narrowing the label leaves its effect on residents in place.",
      ["Keep the labels for internal use but hide them from residents, so routing stays unchanged while avoiding offense.", "Hidden labels still shape how quickly residents are contacted, so the unfair effect continues unseen."],
      ["Have Claude work out which residents prefer short messages, and keep the uncooperative label as an internal note for staff.", "The inference has no supporting evidence, and the unsupported judgment stays attached to residents' requests."],
      ["Review the longer requests by hand, since they contain more evidence for staff to route the request correctly.", "The observed error affects short requests, so reviewing long ones leaves the harmed group unchecked."],
      ["Route on stated service needs, drop the label, check short and long requests for uneven errors, and let staff fix the routing.", "This removes the unsupported judgment, measures the observed risk, and keeps people able to fix consequential routing."]),
    item("correction-codes", "7.2", "eval", "Harbor events office",
      "Staff reviewed 40 event drafts from a shared Project. Nine edits corrected the same venue capacity rule, which the venue changed in January; the project knowledge file still shows the old rule. Three edits were unrelated style changes. The coordinator can make one change before Friday's batch. Which revision should be tried first?",
      "a", "Use feedback to find the most consequential repeated failure and fix its source, then recheck the exact cases it affected. Style edits, bulk review logs and length targets do not address a stale fact that keeps reappearing from knowledge.",
      ["Replace the venue rules file in project knowledge with the January version, then rerun the nine drafts that needed the same fix.", "The common cause is fixed at its source, and rerunning the nine drafts confirms the correction took effect."],
      ["Add the three style edits to the Project instructions first, since they are quick to describe and easy for Claude to follow.", "Quick wins do not touch the nine capacity errors, which will recur from the outdated knowledge file."],
      ["Paste the full review log of 40 drafts into the Project instructions so Claude learns from each reviewer correction.", "The stale file remains in knowledge, and a long log of edits buries the standing rules in noise."],
      ["Measure whether Friday's drafts are shorter than this week's, since shorter drafts leave less room for capacity errors.", "Length is unrelated to the capacity rule; a short draft can still quote the outdated limit."]),
    item("july-associate-open-studio", "1.1", "prompt", "Open studio reminder",
      "A signed schedule lists exhibitor setup at 8:30, visitor admission at 10:00 and staff checkout at 4:00. The studio needs a two-line text message for visitors. A first request, 'Summarize the schedule for a text,' returned 'Doors open 8:30!' and was nearly sent to 400 visitors. Which request is most useful?",
      "b", "Name the reader, the controlling source field, the action and the format. When a source mixes events for different audiences, an unspecified summary lets Claude pick the wrong one. Ordering rules, old messages and 'earliest activity' cues all leave the audience-relevant time unstated.",
      ["Summarize the whole signed schedule in two lines for a text message, keeping each of the three times in the order given.", "Cramming all three times into two lines still foregrounds setup and checkout, which visitors do not need."],
      ["From the signed schedule, write two lines for visitors with the 10:00 admission time and where to ask about access.", "It defines the audience, the controlling field and the action, so the 8:30 setup time cannot be mistaken for admission."],
      ["Reuse last season's visitor text and keep its arrival time, updating only the date so the message stays familiar.", "An earlier message can guide style but does not establish this season's schedule or admission time."],
      ["Write a friendly two-line update that leads with the earliest activity of the day so visitors arrive in good time.", "The earliest activity is exhibitor setup, so this reproduces the 8:30 error that nearly went out."]),
    item("july-associate-workshop-research", "3.1", "claudeResearch", "Regional workshop comparison",
      "An organizer on a paid Claude plan must compare three regional workshops on cost, schedule and accessibility. One workshop's page links to a separate, more recent accessibility statement, and two others describe their policies only on partner sites. The organizer will verify findings before publishing. Which capability fits the investigation?",
      "c", "Research suits questions that need several searches that build on each other across sources, returning cited findings to verify. Memory, Artifacts and single-page summaries each have a role, but none of them follows links to newer or external evidence.",
      ["Store the three workshop descriptions in account memory so later chats can reuse them for the comparison and its updates.", "Memory carries context about you across chats; it does not search for newer statements on other sites."],
      ["Create an Artifact from the first description of each workshop and refine the comparison's layout and design in it.", "An Artifact can present the comparison after the source work, but it does not gather the missing evidence."],
      ["Use Research with web search on, so Claude follows links across workshop and partner sites and returns cited findings.", "Research pursues leads across multiple sites, including the newer statement, and cites what the organizer must check."],
      ["Summarize each workshop's main page in a chat and keep the oldest accessibility statement as the baseline for comparison.", "Main pages miss the partner-site policies, and the oldest statement may be superseded by the newer one."]),
    item("july-associate-repair-turnaround", "4.2", "eval", "Neighborhood equipment repair",
      "An eight-case trial cut drafting from 11 to 6 minutes per repair notice. Checking rose from 2 to 8 minutes because the drafts omitted required parts references, which reviewers had to look up themselves. The organizer must decide what to test before a wider rollout. What should the organizer test next?",
      "a", "Look at the whole workflow: total effort went from 13 to 14 minutes, and the evidence points to one specific gap. Test a fix for that gap on matched cases, measuring total time and omissions, instead of adopting on a single-stage gain or excluding the cases that explain the cost.",
      ["Require the parts reference for each repair in the prompt, then time the whole process and count omissions on the same cases.", "This targets the cause of the extra checking and measures the whole process on comparable cases."],
      ["Adopt now, since drafting is five minutes faster, and look at checking time separately in next quarter's review.", "Checking time already erases the drafting saving, so adopting now makes each notice a minute slower overall."],
      ["Ask reviewers to approve on tone alone when a part number is missing, so checking time returns to two minutes.", "That removes verification of a required field rather than fixing the drafts that omit it."],
      ["Rerun the cases that had no parts changes and compare their drafting time with the original manual process for those notices.", "This excludes the very cases that explain the extra review work, so the result says nothing about the fix."]),
    item("july-associate-quilt-project", "5.3", "projects", "Quilting class handoff",
      "Every class confirmation needs the accessibility contact and the current start time in plain language. Rooms and times change each Saturday and are kept in an approved schedule file in project knowledge. The previous coordinator pasted last week's room and time into the Project instructions, and two confirmations went out with stale times. What belongs in the Project instructions?",
      "d", "Persistent instructions describe recurring behavior and point to where changing facts live; they should not hold the facts themselves. Values pasted into instructions go stale, and examples or past drafts carry old details forward. Write the rule once and let the maintained source supply the values.",
      ["The room and start time from the most recent confirmation, updated by whoever sends the first confirmation each Saturday.", "Facts in instructions go stale whenever someone forgets the update, which is how two wrong times went out."],
      ["The latest schedule pasted in full as an example of tone, so Claude can match both its wording and its times.", "Pasting the full schedule into instructions repeats the stale-fact problem and mixes factual evidence with style guidance."],
      ["Each previous confirmation pasted in full, with a request that Claude imitate the one that best fits each new class.", "Old confirmations carry last season's times and rooms, and imitating them lets those stale details resurface in new ones."],
      ["A rule to state the start time from the approved schedule file and the accessibility contact, in plain language.", "The rule recurs unchanged, while the schedule file in knowledge supplies the current time each week."]),
    item("july-associate-aggregate-boundary", "6.2", "privacy", "After-school equipment survey",
      "An outside analyst may receive weekly equipment-use counts only. The internal sheet has student names and free-text notes. A coordinator proposes uploading the full sheet to an incognito chat, asking Claude for weekly totals, and deleting the chat afterward. The staff system can compute the totals itself. What should happen?",
      "b", "When policy allows only aggregates to leave, compute the aggregate inside the approved environment before anything crosses the boundary. Incognito, private Projects and deletion manage retention and visibility, not what was disclosed when the full sheet was uploaded.",
      ["Use an incognito chat as proposed, and instruct Claude to show only weekly counts so no names appear in the output.", "Incognito controls history and memory; names and notes would still be uploaded before any counts are produced."],
      ["Compute weekly totals within the staff system and share only those totals, so names and notes never leave it.", "The aggregate is prepared inside the boundary, so only the permitted counts ever reach the analyst."],
      ["Replace names with initials and share the original notes, so the analyst can check the weekly totals against them.", "Record-level notes are outside the approved aggregate and can identify students even without full names."],
      ["Upload the sheet to a private Project and allow only the resulting chart to be shared with the outside analyst.", "Restricting what is shared afterward does not undo uploading names and notes in the first place."]),
    item("july-associate-checkout-diagnosis", "7.1", "eval", "Community art supply checkout",
      "The same drafting prompt extracts pickup times correctly from printed signup sheets but misses them on online forms, where the field is labeled 'Collect after.' Both sources give identical times for the same 20 orders. The model and Project instructions are unchanged, and three customers have already arrived too early. What is the most useful first test?",
      "c", "Reproduce a failure with matched records that differ only in the suspected condition. When two sources carry the same facts but one fails, the representation is the likely cause. Length changes, combined fixes and testing the working path cannot isolate it.",
      ["Increase the output length allowed for online forms and compare the word count of the resulting pickup reminder messages.", "Word count cannot show whether the 'Collect after' field is now read as the pickup time."],
      ["Switch the model and rewrite the prompt template at the same time, then rerun the online forms to check results.", "Two simultaneous changes leave the cause unknown, even if the online forms start working after the rerun."],
      ["Replay paired records from both sources, differing only in the field label, and compare the extracted pickup times.", "Only the label varies, so a difference in extracted times isolates how the field is being interpreted."],
      ["Test more printed sheets before changing anything, to confirm the prompt still handles the format that already works.", "Printed sheets already work and never exercise the failing online path, so this test reveals nothing new."]),
  ],
  followup: [
    item("gallery-label", "1.1", "prompt", "Harbor Gallery",
      "A curator needs an 80-word label for children aged 7 to 10 about a carved chest. The object record names the maker and dates the chest 'about 1850–1870.' A first prompt, 'Write a fun museum label,' returned 'made in 1862' and an anecdote that is not in the record. How should the curator brief Claude?",
      "b", "A strong brief states the audience, length and source, and protects the precision of what the source actually knows. Without that, Claude supplies confident specifics and stories. Examples help with style, and simplification helps with reading level, but neither tells Claude where facts must come from.",
      ["Ask for an engaging label and let Claude supply a precise year and a story from what is known about the period.", "The record does not support a precise year, and a period story invents facts the museum cannot stand behind."],
      ["Write 80 words for ages 7 to 10 using only the object file, keeping the date range and leaving out unrecorded stories.", "It defines the reader, length and source, and explicitly protects the record's date precision and content."],
      ["Ask for an academic description of the chest first, then simplify its longest sentences so younger readers can follow it.", "Shortening sentences does not adapt vocabulary for children, and the academic draft can still add specifics."],
      ["Give two sample labels from other objects and let Claude fill missing facts from objects of the same era.", "Examples can guide style, but filling facts from other objects is invention presented as this chest's history."]),
    item("rebate-claim", "2.3", "grounding", "Energy Advice Desk",
      "A draft energy-advice email says 'every household gets a $200 rebate.' The linked program page says households under the income cap may receive up to $200, depending on the upgrade installed. The email goes to 6,000 subscribers, many above the cap. The program manager wants the claim kept to one sentence. Which edit is supported by the source?",
      "c", "Check every qualifier in the source against the claim: who is eligible, how much, and under what conditions. Fixing one qualifier while leaving another too broad still misleads readers. A supported claim carries the source's limits and points to the criteria.",
      ["Say every household can expect a rebate of up to $200, and link to the program page for further details.", "The amount is now capped, but 'every household' still ignores the income cap that excludes many subscribers."],
      ["Say eligible households receive a $200 rebate, and link to the program page so readers can confirm eligibility.", "Eligibility is now limited, but the source promises up to $200 depending on the upgrade, not a fixed $200."],
      ["Say households under the income cap may receive up to $200 depending on the upgrade, and link to the eligibility criteria.", "Both the eligibility limit and the conditional maximum from the source are preserved in one sentence."],
      ["Remove the dollar amount and say the rebate program is open to every household that installs an upgrade.", "Dropping the figure does not fix eligibility; the program is still limited to households under the income cap."]),
    item("chapter-handoff", "3.1", "projects", "Orchard Press",
      "Editors work on separate chapters in separate chats. They are members of the same Team-plan Project and need the current style guide and glossary in every chat. Chapter manuscripts have separate permissions and must not be visible to other editors. Last month one editor used an outdated glossary. Where should the team put the common references?",
      "a", "Shared reference material belongs in the knowledge of a Project whose membership matches who may see it. Keep material with narrower permissions out of that shared scope. Chat attachments, examples and single threads either fail to share or share too much.",
      ["Add the current style guide and glossary to the shared Project's knowledge, keeping chapter files out of the Project.", "Every chat gets the same current references, and private manuscripts stay outside the shared scope."],
      ["Attach both documents to the first chapter chat, so later chats in the Project can draw on that chat's attachments.", "Attachments stay with their chat; later chats do not inherit them, so editors drift to their own copies."],
      ["Put one finished chapter in an Artifact as a reference, so editors can infer the style and glossary terms from it.", "One chapter shows a sample, not the full guide or glossary, and it exposes a manuscript to other editors."],
      ["Keep the chapters and both references in one long shared thread, so the glossary stays in the same context as each chapter.", "This mixes every manuscript into one context, which breaks the separate permissions on chapter files."]),
    item("order-proof", "4.4", "eval", "Bay Street Bakery",
      "Claude can draft order confirmations from web order forms. The owner requires a person to check allergy notes against the original form before any confirmation is sent, after a nut-allergy mix-up last year. The bakery wants a four-week pilot that measures impact while meeting that requirement. Which pilot design fits?",
      "d", "Keep a mandated pre-release check on every case and measure the whole workflow, including review effort, so the pilot reflects real conditions. Confidence-based sending, conditional review and side-by-side reading speed either break the requirement or measure the wrong thing.",
      ["Send high-confidence confirmations automatically, and audit a sample of their allergy notes against the order forms each Friday afternoon.", "A Friday audit happens after sending, which breaks the owner's requirement for a check before each confirmation."],
      ["Review the confirmations where Claude's draft mentions an allergy note, and send the remaining orders straight to customers.", "If the draft drops an allergy note from the form, that order skips review, which is the failure the rule prevents."],
      ["Have staff draft as usual for the pilot and measure how quickly Claude can read an order form on the side.", "Reading speed is not a changed workflow, so the pilot would say nothing about impact on real confirmations."],
      ["Draft from forms, have staff check allergy notes against each original before sending, and log the minutes this adds.", "The required check happens on each order before sending, and review minutes capture the true cost of the workflow."]),
    item("closing-checklist", "5.4", "projects", "Marina Operations",
      "For two months, replies from the marina operations Project have sometimes cited a closing checklist withdrawn in September. Both checklist-v3 and checklist-v4 are in project knowledge. The Project instructions and the reply Skill have not changed since summer. A colleague suggests switching to Opus. Which intervention tests the root cause?",
      "b", "Fix the layer the symptom points to and test with a case that separates the versions. A withdrawn file still in knowledge is a stale-knowledge cause; new chats, formatting and stronger models all leave it eligible. A test on unchanged behavior cannot show the fix worked.",
      ["Repeat the same request in a new chat inside the Project, leaving both checklists in knowledge, to see whether the old checklist is cited again.", "A new chat reads the same knowledge, so recurrence or not is chance; the withdrawn file is still available."],
      ["Remove checklist-v3 from project knowledge, then test a closing question whose answer changed between the two checklist versions.", "The withdrawn source is gone, and the test passes only if the current checklist is the one Claude uses."],
      ["Keep both checklists and require numbered bullet points in each answer so staff can spot the withdrawn steps.", "Formatting makes errors easier to see but leaves the withdrawn checklist eligible to be cited."],
      ["Switch the Project to Opus with both checklists still in knowledge, since a stronger model should prefer the newer checklist.", "Capability does not resolve which file governs; with both present, Opus can cite the old one fluently."]),
    item("notes-policy", "6.2", "privacy", "Regional Food Bank",
      "Policy permits aggregate delivery themes in the food bank's approved Claude workspace but excludes recipient addresses. A coordinator wants to review 300 delivery reports for recurring problems, and many reports mention street addresses in their free-text notes. The reports export from the volunteer system as a spreadsheet. Which TWO actions support the delivery review?",
      "ce", "Minimize inputs before processing, paying special attention to free text, and confirm that the specific workflow fits policy. Output instructions, Project placement and private chats manage what is shown or who sees it, not what was disclosed at upload.",
      ["Upload the address-bearing reports as they are, and ask Claude to respond only with aggregate themes and no street names.", "The excluded addresses would enter the workspace at upload, before any instruction about the output could apply."],
      ["Keep street numbers in the reports within a shared Project so Claude can group incidents by neighborhood during the analysis.", "Street numbers are part of the excluded address data, regardless of how useful they would be for grouping."],
      ["Remove addresses from the notes locally and send only the minimum excerpts needed to code the delivery themes.", "This limits submitted data to the approved task and screens the free text where addresses hide."],
      ["Have staff paste reports into private chats in the same workspace, which keeps addresses away from other users.", "A private chat limits who sees the content but does not override the restriction on uploading addresses."],
      ["Confirm in writing with the designated data owner that the redacted workflow and its fields meet the organization's policy.", "Owner confirmation checks the actual proposed use and inputs rather than assuming workspace access equals approval."]),
    item("returns-export", "7.1", "eval", "Harbor Outfitters",
      "A returns summary has missed about a third of returned items since the export changed the status 'Returned' to the code R. No other changes were deployed, and the prompt and model are the same. Last month's export is still available. A colleague suggests rewriting the prompt and switching models together. Which test would give the clearest evidence?",
      "a", "Hold the prompt and model fixed and compare the old and new representations on matched rows. One controlled difference gives clear evidence of cause. Simultaneous changes, model self-reports and mention counts cannot show which records were handled correctly.",
      ["Run the same orders from the old and new exports through one prompt and model, and see which returns each version of the export catches.", "Only the encoding differs, so any gap in caught returns isolates the status code as the cause."],
      ["Replace the model and revise the prompt before the next live run, then check whether the weekly returns summary improves.", "Two changes at once obscure the cause, and live data offers no matched comparison with the old export."],
      ["Run the newest rows by themselves and ask Claude whether it understands what the R status code means in this export.", "A self-report is weaker evidence than a controlled comparison of actual results against the old export."],
      ["Ask for longer, more detailed summaries and count how many times returns are mentioned compared with last month's summary.", "Mention counts do not show which returned items were actually identified, so the cause stays untested."]),
  ],
};
